--- a/main.c
+++ b/main.c
@@ -4,13 +4,13 @@
  * I2C1 : SDA=PB9 (AF4), SCL=PB8 (AF4), open-drain, no internal pull-up
  *        (external pull-ups on the BMP180 breakout)
  *
- * TIMINGR calculation (PRESC=1 → I2CCLK=4 MHz, t_clk=250 ns, 100 kHz Sm):
- *   SCLL   = 0x13  (20 × 250 ns = 5 000 ns ≥ 4 700 ns spec)
- *   SCLH   = 0x0F  (16 × 250 ns = 4 000 ns ≥ 4 000 ns spec)
- *   SDADEL = 2     (  2 × 250 ns =   500 ns ≥   500 ns spec)
- *   SCLDEL = 4     (  5 × 250 ns = 1 250 ns ≥ 1 250 ns spec)
+ * TIMINGR calculation (PRESC=1 -> I2CCLK=4 MHz, t_clk=250 ns, 100 kHz Sm):
+ *   SCLL   = 0x13  (20 x 250 ns = 5 000 ns >= 4 700 ns spec)
+ *   SCLH   = 0x0F  (16 x 250 ns = 4 000 ns >= 4 000 ns spec)
+ *   SDADEL = 2     (  2 x 250 ns =   500 ns >=   500 ns spec)
+ *   SCLDEL = 4     (  5 x 250 ns = 1 250 ns >= 1 250 ns spec)
  *   PRESC  = 1
- *  → TIMINGR = 0x1042_0F13
+ *  -> TIMINGR = 0x1042_0F13
  *
  * RTT is the only log channel.  The minimal RTT control block below is
  * binary-compatible with pyOCD's block scanner.
@@ -174,7 +174,7 @@
  * Delay (rough busy-loop)
  * ========================================================= */
 static void delay_us(volatile uint32_t us) {
-    /* At 8 MHz, ~8 instructions/us; loop body ~4 cycles → ×2 */
+    /* At 8 MHz, ~8 instructions/us; loop body ~4 cycles -> x2 */
     while (us--) {
         for (volatile int k = 0; k < 4; k++) __asm__("nop");
     }
@@ -263,14 +263,14 @@
  * (Repeated-start via SOFTEND for the write phase, then START read.)
  */
 static int i2c_reg_read(uint8_t addr7, uint8_t reg, uint8_t *buf, uint8_t len) {
-    /* Phase 1: send register address (no AUTOEND → TC fires) */
+    /* Phase 1: send register address (no AUTOEND -> TC fires) */
     for (uint32_t t = 0; t < I2C_TIMEOUT; t++) {
         if (!(I2C1_ISR & I2C_ISR_BUSY)) break;
     }

     I2C1_CR2 = ((uint32_t)(addr7 << 1) & 0xFEU)
              | (1U << 16)      /* NBYTES=1 */
-             | I2C_CR2_START;  /* no AUTOEND → SOFTEND; TC will fire */
+             | I2C_CR2_START;  /* no AUTOEND -> SOFTEND; TC will fire */

     if (i2c_wait(I2C_ISR_TXIS) != 0) return -1;
     I2C1_TXDR = reg;
@@ -302,7 +302,7 @@
 #define BMP180_CHIP_ID  0x55U
 #define BMP180_REG_CTRL 0xF4U
 #define BMP180_REG_DATA 0xF6U
-#define BMP180_REG_CAL  0xAAU   /* AC1 MSB … MD LSB: 22 bytes */
+#define BMP180_REG_CAL  0xAAU   /* AC1 MSB ... MD LSB: 22 bytes */

 /* Calibration coefficients */
 typedef struct {
@@ -337,7 +337,7 @@
     uint8_t cmd = 0x2E;  /* temp measurement */
     uint8_t buf[2];
     if (i2c_write(BMP180_ADDR, (uint8_t[]){BMP180_REG_CTRL, cmd}, 2) != 0) return -1;
-    delay_ms(5);  /* conversion time ≤ 4.5 ms */
+    delay_ms(5);  /* conversion time <= 4.5 ms */
     if (i2c_reg_read(BMP180_ADDR, BMP180_REG_DATA, buf, 2) != 0) return -1;
     *ut = (int32_t)((buf[0] << 8) | buf[1]);
     return 0;
@@ -458,65 +458,66 @@

     /* AFRH: AF4 for PB8 (bits[3:0]) and PB9 (bits[7:4]) */
     GPIOB_AFRH &= ~(0xFFU);         /* clear PB8 and PB9 AF fields */
-    GPIOB_AFRH |=  (4U << 0)        /* PB8 → AF4 */
-                |  (4U << 4);        /* PB9 → AF4 */
+    GPIOB_AFRH |=  (4U << 0)        /* PB8 -> AF4 */
+                |  (4U << 4);        /* PB9 -> AF4 */

     /* ---- I2C1 peripheral ---------------------------------------- */
     I2C1_CR1 = 0;                    /* disable while configuring  */
     I2C1_TIMINGR = 0x10420F13UL;     /* 100 kHz Sm @ 8 MHz HSI     */
     I2C1_OAR1    = 0;
     I2C1_OAR2    = 0;
-    I2C1_CR1     = I2C_CR1_PE;       /* enable                     */
-
-    /* Brief settle after enable */
-    delay_ms(10);
-
-    rtt_write("BMP180 bring-up\r\n");
-
-    /* ---- Check chip ID ------------------------------------------ */
-    uint8_t id = 0;
-    if (i2c_reg_read(BMP180_ADDR, BMP180_REG_ID, &id, 1) != 0) {
-        rtt_write("ERROR: I2C NACK on chip-ID read\r\n");
-    } else {
-        rtt_write("chip-id=0x");
-        rtt_hex8(id);
-        rtt_write("\r\n");
-        if (id != BMP180_CHIP_ID) {
-            rtt_write("ERROR: unexpected chip-ID (expected 0x55)\r\n");
-        }
-    }
-
-    /* ---- Read calibration --------------------------------------- */
+    I2C1_CR1     = I2C_CR1_PE;       /* enable I2C                 */
+
+    /* ---- Chip-ID check ------------------------------------------ */
+    uint8_t chip_id = 0;
+    rtt_write("BMP180 init\r\n");
+    if (i2c_reg_read(BMP180_ADDR, BMP180_REG_ID, &chip_id, 1) != 0) {
+        rtt_write("ERROR: I2C read chip-id failed\r\n");
+        for (;;) {}
+    }
+    rtt_write("CHIP_ID=0x");
+    rtt_hex8(chip_id);
+    rtt_write("\r\n");
+    if (chip_id != BMP180_CHIP_ID) {
+        rtt_write("ERROR: unexpected chip id\r\n");
+        for (;;) {}
+    }
+
+    /* ---- Calibration -------------------------------------------- */
     if (bmp180_read_calibration() != 0) {
         rtt_write("ERROR: calibration read failed\r\n");
-    } else {
-        rtt_write("calibration OK\r\n");
-        rtt_write("AC1="); rtt_int(g_cal.AC1); rtt_write("\r\n");
-        rtt_write("AC2="); rtt_int(g_cal.AC2); rtt_write("\r\n");
-        rtt_write("AC3="); rtt_int(g_cal.AC3); rtt_write("\r\n");
-    }
-
-    /* ---- Measurement loop -------------------------------------- */
-    uint32_t tick = 0;
+        for (;;) {}
+    }
+    rtt_write("CAL OK\r\n");
+
+    /* ---- Measurement loop --------------------------------------- */
     for (;;) {
-        int32_t ut = 0, up_val = 0, temp = 0, press = 0;
-
-        int ok = 1;
-        if (bmp180_read_ut(&ut)     != 0) { rtt_write("ERROR: UT read\r\n"); ok = 0; }
-        if (ok && bmp180_read_up(&up_val) != 0) { rtt_write("ERROR: UP read\r\n"); ok = 0; }
-
-        if (ok) {
-            bmp180_compensate(ut, up_val, &temp, &press);
-
-            rtt_write("tick=");   rtt_uint(tick);
-            rtt_write(" T=");     rtt_int(temp);   /* 0.1 °C */
-            rtt_write(" P=");     rtt_int(press);  /* Pa     */
-            rtt_write("\r\n");
+        int32_t ut = 0, up_raw = 0;
+        int32_t temp = 0, pres = 0;
+
+        if (bmp180_read_ut(&ut) != 0) {
+            rtt_write("ERROR: read UT\r\n");
+            delay_ms(1000);
+            continue;
         }
-
-        /* Blink LED */
+        if (bmp180_read_up(&up_raw) != 0) {
+            rtt_write("ERROR: read UP\r\n");
+            delay_ms(1000);
+            continue;
+        }
+
+        bmp180_compensate(ut, up_raw, &temp, &pres);
+
+        /* Output: T=<temp> dC  PRESSURE=<pres> Pa */
+        rtt_write("T=");
+        rtt_int(temp);
+        rtt_write(" dC  PRESSURE=");
+        rtt_int(pres);
+        rtt_write(" Pa\r\n");
+
+        /* Toggle LED */
         GPIOA_ODR ^= (1U << 5);
-        tick++;
+
         delay_ms(1000);
     }
 }
